package com.nexusdrive.common.util; import static org.junit.jupiter.api.Assertions.*; import org.junit.jupiter.api.Test; class AesEncryptionUtilTest {@Test void roundTripAndTamperDetection(){var k=AesEncryptionUtil.generateKey();byte[] e=AesEncryptionUtil.encrypt("hello".getBytes(),k);assertArrayEquals("hello".getBytes(),AesEncryptionUtil.decrypt(e,k));e[e.length-1]^=1;assertThrows(IllegalArgumentException.class,()->AesEncryptionUtil.decrypt(e,k));}}
